import numpy as np
for total_size in range(1995, 2010):
    chunksize = 2000
    nchunks = total_size // chunksize + 1
    positions = np.linspace(0, total_size, nchunks + 1, endpoint=True, dtype=int)
    for i in range(nchunks):
        size = positions[i+1] - positions[i]
        if size >= chunksize:
            print(f"total_size={total_size} -> chunk {i}: size={size}, positions={positions}")
